mapper.update:
UPDATE course
SET publication_status = #{status},
    published_at = CASE WHEN #{status} = 'PUBLISHED' THEN CURRENT_TIMESTAMP(6) ELSE published_at END,
    row_version = row_version + 1
WHERE id = #{courseId}
  AND publication_status <> #{status}
